      "cache.c": "// Files are combined in displayed order; standard C headers are supplied.\n// Strings/clock are borrowed and must outlive the cache; free internal storage in cache_destroy.\ntypedef enum { VALUE_NULL, VALUE_BOOL, VALUE_NUMBER, VALUE_STRING } ValueKind;\ntypedef struct { ValueKind kind; double number; const char *text; } Value;\ntypedef struct { const char *key; Value value; long long expires; } CacheEntry;\ntypedef struct { const long long *now; CacheEntry *entries; size_t n; } Cache;\nCache cache_create(const long long*now){return (Cache){now,NULL,0};}\nstatic void cache_remove(Cache*c,size_t i){c->entries[i]=c->entries[--c->n];}\nvoid cache_set(Cache*c,const char*key,Value value,long long ttl){size_t i=0;while(i<c->n&&strcmp(c->entries[i].key,key))i++;if(ttl<=0){if(i<c->n)cache_remove(c,i);return;}if(i==c->n){CacheEntry*p=realloc(c->entries,(c->n+1)*sizeof(*p));if(!p)exit(2);c->entries=p;c->n++;}c->entries[i]=(CacheEntry){key,value,*c->now+ttl};}\nbool cache_get(Cache*c,const char*key,Value*out){for(size_t i=0;i<c->n;i++)if(!strcmp(c->entries[i].key,key)){if(*c->now>=c->entries[i].expires){cache_remove(c,i);return false;}*out=c->entries[i].value;return true;}return false;}\nsize_t cache_size(Cache*c){for(size_t i=0;i<c->n;)if(*c->now>=c->entries[i].expires)cache_remove(c,i);else i++;return c->n;}\nvoid cache_destroy(Cache*c){free(c->entries);c->entries=NULL;c->n=0;}\n",
