      "order.c": "typedef struct { int id; double created_at; } Record;\n// next_cursor==0 means no cursor (record IDs are positive). invalid limits set valid=false.\ntypedef struct { Record *items; size_t n; int next_cursor; bool valid; } Page;\nstatic int record_cmp(const void*a,const void*b){const Record*x=a,*y=b;if(x->created_at!=y->created_at)return x->created_at>y->created_at?-1:1;return (y->id>x->id)-(y->id<x->id);}\nRecord*order(const Record*records,size_t n){Record*copy=n?malloc(n*sizeof(*copy)):NULL;if(n&&!copy)exit(2);if(n){memcpy(copy,records,n*sizeof(*copy));qsort(copy,n,sizeof(*copy),record_cmp);}return copy;}\n",
