      "summary.c": "typedef struct {Event value;size_t index;} IndexedEvent;\nstatic int event_id_cmp(const void*a,const void*b){const IndexedEvent*x=a,*y=b;int order=strcmp(x->value.id,y->value.id);if(order)return order;return (x->index>y->index)-(x->index<y->index);}\nstatic int event_user_cmp(const void*a,const void*b){const IndexedEvent*x=a,*y=b;return strcmp(x->value.user,y->value.user);}\nSummary summarize(const Event*events,size_t n,double start,double end){IndexedEvent*valid=n?malloc(n*sizeof(*valid)):NULL;if(n&&!valid)exit(2);size_t count=0;for(size_t i=0;i<n;i++){Event e;if(normalize(&events[i],&e))valid[count++]=(IndexedEvent){e,i};}if(count)qsort(valid,count,sizeof(*valid),event_id_cmp);size_t used=0;for(size_t i=0;i<count;){size_t next=i+1;while(next<count&&!strcmp(valid[i].value.id,valid[next].value.id))next++;if(valid[i].value.timestamp>=start&&valid[i].value.timestamp<end)valid[used++]=valid[i];i=next;}if(used)qsort(valid,used,sizeof(*valid),event_user_cmp);Summary s={used?calloc(used,sizeof(UserTotal)):NULL,0,0};if(used&&!s.users)exit(2);for(size_t i=0;i<used;i++){Event e=valid[i].value;if(!s.n||strcmp(s.users[s.n-1].user,e.user))s.users[s.n++]=(UserTotal){e.user,0,0};s.users[s.n-1].count++;s.users[s.n-1].amount+=e.amount;s.total+=e.amount;}free(valid);return s;}\n"
